def assign_initial_tiers(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    User.objects.filter(
        models.Q(is_staff=True) | models.Q(is_superuser=True)
    ).update(tier="god")
    User.objects.filter(is_staff=False, is_superuser=False).update(tier="novice")


